import { useEffect, useMemo, useState } from "react";
import {
  Box,
  Button,
  Container,
  IconButton,
  Radio,
  Stack,
  Typography,
  useMediaQuery,
} from "@mui/material";
import { useTheme } from "@mui/material/styles";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import type { HomePlans, PlanCard } from "../types/home";
import plansBg from "../assets/Frame-1000005851.png";

const BLUE = "#759ae1";
const NAVY = "#17224d";

function Heading({ title, highlight }: { title?: string; highlight?: string }) {
  if (!title && !highlight) return null;
  if (title && highlight && title.includes(highlight)) {
    const index = title.indexOf(highlight);
    return (
      <>
        {title.slice(0, index)}
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
        {title.slice(index + highlight.length)}
      </>
    );
  }
  return (
    <>
      {title}{" "}
      {highlight ? (
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
      ) : null}
    </>
  );
}

function PlanItem({
  plan,
  selected,
  onSelect,
}: {
  plan: PlanCard;
  selected: string;
  onSelect: (duration: string) => void;
}) {
  const canBuy = Boolean(plan.buyUrl && selected);

  return (
    <Box
      sx={{
        width: "100%",
        minWidth: 0,
        backgroundColor: "#fff",
        borderRadius: "15px",
        boxShadow: "0 4px 20px 0 rgba(0,0,0,0.10)",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        minHeight: { xs: "auto", md: 560 },
      }}
    >
      <Box
        sx={{
          backgroundColor: "#e7efff",
          borderTopLeftRadius: "15px",
          borderTopRightRadius: "15px",
          minHeight: 138,
          px: 3,
          py: 3,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}
      >
        <Typography
          sx={{
            fontSize: { xs: 22, md: 26 },
            fontWeight: 700,
            letterSpacing: "0.26px",
            lineHeight: 1.2,
            mb: 1.5,
            background: "linear-gradient(180deg, #17224d 0%, #759ae1 100%)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
          }}
        >
          {plan.title}
        </Typography>
        {plan.learnMoreUrl ? (
          <Box
            component="a"
            href={plan.learnMoreUrl}
            target="_blank"
            rel="noopener noreferrer"
            sx={{
              color: BLUE,
              fontWeight: 700,
              fontSize: 16,
              textDecoration: "none",
              width: "fit-content",
            }}
          >
            Learn More
          </Box>
        ) : (
          <Typography sx={{ color: BLUE, fontWeight: 700, fontSize: 16 }}>Learn More</Typography>
        )}
      </Box>
      <Box sx={{ px: 2.5, py: 2, flex: 1 }}>
        <Stack spacing={0.5}>
          {(plan.prices || []).map((price) => {
            const active = selected === price.duration;
            return (
              <Stack
                key={price.id || price.duration}
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                onClick={() => onSelect(price.duration)}
                sx={{ py: 1, cursor: "pointer" }}
              >
                <Stack direction="row" alignItems="center" spacing={0.5}>
                  <Radio
                    checked={active}
                    onChange={() => onSelect(price.duration)}
                    sx={{
                      color: "#9aa3b2",
                      p: 0.5,
                      "&.Mui-checked": { color: BLUE },
                    }}
                  />
                  <Typography sx={{ color: NAVY, fontSize: 16, fontWeight: 500 }}>
                    {price.duration}
                  </Typography>
                </Stack>
                <Box sx={{ textAlign: "right" }}>
                  <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 16 }}>
                    {price.price}
                  </Typography>
                  {price.strikePrice ? (
                    <Typography
                      sx={{
                        textDecoration: "line-through",
                        color: "rgba(106,106,106,0.65)",
                        fontSize: 16,
                        fontWeight: 500,
                      }}
                    >
                      {price.strikePrice}
                    </Typography>
                  ) : null}
                </Box>
              </Stack>
            );
          })}
        </Stack>
      </Box>
      <Box sx={{ borderTop: "1px solid rgba(128,128,128,0.64)", py: 2.5, textAlign: "center" }}>
        <Button
          variant="contained"
          href={canBuy ? plan.buyUrl : undefined}
          target="_blank"
          rel="noopener noreferrer"
          disabled={!canBuy}
          sx={{
            width: 169,
            backgroundColor: BLUE,
            color: "#fff",
            fontWeight: 700,
            borderRadius: "5px",
            boxShadow: "none",
            opacity: canBuy ? 1 : 0.6,
            "&:hover": { backgroundColor: "#5f86d4", boxShadow: "none" },
            "&.Mui-disabled": { backgroundColor: BLUE, color: "#fff", opacity: 0.6 },
          }}
        >
          Buy Plan
        </Button>
      </Box>
    </Box>
  );
}

export default function Plans({ data }: { data?: HomePlans | null }) {
  const theme = useTheme();
  const twoUp = useMediaQuery(theme.breakpoints.up("md"));
  const [tab, setTab] = useState(0);
  const [start, setStart] = useState(0);
  const [selected, setSelected] = useState<Record<number, string>>({});

  const current = data?.tabs?.[tab];
  const plans = useMemo(() => current?.plans || [], [current]);
  const visibleCount = twoUp ? 2 : 1;
  const maxStart = Math.max(0, plans.length - visibleCount);

  useEffect(() => {
    setStart(0);
    setSelected({});
  }, [tab]);

  useEffect(() => {
    setStart((value) => Math.min(value, maxStart));
  }, [maxStart]);

  if (!data) return null;

  const visible = plans.slice(start, start + visibleCount);
  const dotCount = maxStart + 1;

  return (
    <Box
      sx={{
        py: { xs: 6, md: 8 },
        backgroundColor: "#f5fafe",
        backgroundImage: `url(${plansBg})`,
        backgroundRepeat: "no-repeat",
        backgroundSize: "contain",
        backgroundPosition: "top left",
      }}
    >
      <Container maxWidth="lg">
        <Typography
          sx={{
            textAlign: "center",
            color: NAVY,
            fontSize: { xs: 24, md: 36 },
            fontWeight: 700,
            lineHeight: 1.15,
            mb: { xs: 3, md: 5 },
          }}
        >
          <Heading title={data.title} highlight={data.highlight} />
        </Typography>

        <Stack
          direction="row"
          justifyContent="center"
          flexWrap="wrap"
          useFlexGap
          sx={{ gap: { xs: 0.5, md: 1 }, mb: { xs: 3, md: 5 } }}
        >
          {(data.tabs || []).map((item, index) => {
            const active = tab === index;
            return (
              <Button
                key={item.id || item.name}
                onClick={() => setTab(index)}
                sx={{
                  minWidth: { xs: 88, md: 140 },
                  color: BLUE,
                  fontWeight: 600,
                  fontSize: { xs: 13, md: 16 },
                  textTransform: "none",
                  borderRadius: "8px",
                  backgroundColor: active ? BLUE : "transparent",
                  ...(active ? { color: "#fff" } : {}),
                  "&:hover": {
                    backgroundColor: active ? "#5f86d4" : "rgba(117,154,225,0.12)",
                  },
                }}
              >
                {item.name}
              </Button>
            );
          })}
        </Stack>

        <Box sx={{ position: "relative", maxWidth: 1000, mx: "auto" }}>
          <Stack direction="row" spacing={{ xs: 1.25, md: 1.5 }} alignItems="stretch">
            {visible.map((plan) => {
              const key = plan.id || 0;
              return (
                <Box key={plan.id || plan.title} sx={{ flex: 1, minWidth: 0 }}>
                  <PlanItem
                    plan={plan}
                    selected={selected[key] || ""}
                    onSelect={(duration) => setSelected((prev) => ({ ...prev, [key]: duration }))}
                  />
                </Box>
              );
            })}
          </Stack>

          {plans.length > visibleCount ? (
            <>
              <IconButton
                onClick={() => setStart((value) => Math.max(0, value - 1))}
                disabled={start === 0}
                sx={{
                  position: "absolute",
                  left: { xs: -8, md: -48 },
                  top: "45%",
                  transform: "translateY(-50%)",
                  backgroundColor: "#fff",
                  boxShadow: "0 2px 10px rgba(0,0,0,0.12)",
                  "&:hover": { backgroundColor: "#fff" },
                }}
              >
                <ChevronLeftIcon />
              </IconButton>
              <IconButton
                onClick={() => setStart((value) => Math.min(maxStart, value + 1))}
                disabled={start >= maxStart}
                sx={{
                  position: "absolute",
                  right: { xs: -8, md: -48 },
                  top: "45%",
                  transform: "translateY(-50%)",
                  backgroundColor: "#fff",
                  boxShadow: "0 2px 10px rgba(0,0,0,0.12)",
                  "&:hover": { backgroundColor: "#fff" },
                }}
              >
                <ChevronRightIcon />
              </IconButton>
            </>
          ) : null}
        </Box>

        {dotCount > 1 ? (
          <Stack direction="row" justifyContent="center" spacing={1} sx={{ mt: 3 }}>
            {Array.from({ length: dotCount }).map((_, index) => (
              <Box
                key={index}
                onClick={() => setStart(index)}
                sx={{
                  width: 10,
                  height: 10,
                  borderRadius: "50%",
                  cursor: "pointer",
                  backgroundColor: start === index ? BLUE : "rgba(117,154,225,0.35)",
                }}
              />
            ))}
          </Stack>
        ) : null}
      </Container>
    </Box>
  );
}
